import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { GraphIndex, loadGraph } from '../src/graph';
import type { ProbeBank } from '../src/types';

/**
 * The committed probe banks are content, and content generated by a model needs
 * a lint standing over it. Everything checked here would otherwise fail quietly
 * in front of a student: a question about a node that no longer exists, an
 * unanswerable option set, or a bank so lopsided that answer position becomes
 * the tell.
 */

const DATA_DIR = path.resolve(process.cwd(), 'packages/knowledge-graph/data');
const banks = fs.readdirSync(DATA_DIR).filter((f) => f.endsWith('.probes.json'));

const load = (file: string) => {
  const bank = JSON.parse(fs.readFileSync(path.join(DATA_DIR, file), 'utf8')) as ProbeBank;
  const graphFile = file.replace('.probes.json', '.json');
  const index = new GraphIndex(
    loadGraph(JSON.parse(fs.readFileSync(path.join(DATA_DIR, graphFile), 'utf8'))),
  );
  return { bank, index };
};

describe('committed probe banks', () => {
  it('there is at least one', () => {
    expect(banks.length).toBeGreaterThan(0);
  });

  it.each(banks)('%s every probe points at a node that exists', (file) => {
    const { bank, index } = load(file);
    const dangling = bank.probes.filter((p) => index.node(p.nodeId) === null).map((p) => p.id);
    expect(dangling).toEqual([]);
  });

  it.each(banks)('%s one probe per node, no duplicates', (file) => {
    const { bank } = load(file);
    const nodeIds = bank.probes.map((p) => p.nodeId);
    expect(new Set(nodeIds).size).toBe(nodeIds.length);
  });

  it.each(banks)('%s every probe is answerable', (file) => {
    const { bank } = load(file);
    for (const probe of bank.probes) {
      expect(probe.options, probe.id).toHaveLength(4);
      expect(new Set(probe.options).size, `${probe.id} has repeated options`).toBe(4);
      expect(probe.correctIndex, probe.id).toBeGreaterThanOrEqual(0);
      expect(probe.correctIndex, probe.id).toBeLessThan(4);
      expect(probe.question.length, probe.id).toBeGreaterThan(10);
    }
  });

  it.each(banks)('%s every wrong option names a misconception', (file) => {
    const { bank } = load(file);
    // This is what lets the tutor say WHY a student is stuck, so a bank that
    // loses it has lost the thing that makes it more than a quiz.
    for (const probe of bank.probes) {
      if (!probe.misconceptions) continue;
      expect(probe.misconceptions, probe.id).toHaveLength(4);
      expect(probe.misconceptions[probe.correctIndex].trim(), `${probe.id} correct index`).toBe('');
      probe.misconceptions.forEach((m, i) => {
        if (i !== probe.correctIndex) expect(m.length, `${probe.id} option ${i}`).toBeGreaterThan(4);
      });
    }
  });

  it.each(banks)('%s does not leak the answer through position', (file) => {
    const { bank } = load(file);
    // A bank where the answer is usually "C" teaches students to guess C.
    const counts = [0, 0, 0, 0];
    for (const probe of bank.probes) counts[probe.correctIndex] += 1;
    const share = Math.max(...counts) / bank.probes.length;
    expect(share).toBeLessThan(0.45);
  });

  /**
   * Coverage is checked PER CHAPTER, and only for chapters that have been
   * probed at all.
   *
   * Maps grow one chapter at a time across many generation runs, so a chapter
   * with no probes yet is a schedule fact, not a defect — and a whole-map
   * ratio cannot tell that apart from a bank that has lost probes it used to
   * have. Per chapter it can: the generator writes a chapter's probes in one
   * go, so a probed chapter that is only half covered means something was
   * dropped, which is exactly the drift worth failing on.
   */
  it.each(banks)('%s covers every chapter it has started', (file) => {
    const { bank, index } = load(file);
    const covered = new Set(bank.probes.map((p) => p.nodeId));

    const byChapter = new Map<string, { total: number; covered: number }>();
    for (const id of index.ids()) {
      const chapter = index.node(id)?.chapter;
      if (chapter === undefined) continue;
      const tally = byChapter.get(chapter) ?? { total: 0, covered: 0 };
      tally.total += 1;
      if (covered.has(id)) tally.covered += 1;
      byChapter.set(chapter, tally);
    }

    for (const [chapter, tally] of byChapter) {
      if (tally.covered === 0) continue; // not generated yet
      expect(tally.covered / tally.total, `${file} chapter "${chapter}"`).toBeGreaterThan(0.8);
    }
  });

  it.each(banks)('%s has enough probes to run a diagnostic at all', (file) => {
    const { bank } = load(file);
    // The placement test asks up to twenty questions and never repeats a node.
    expect(bank.probes.length).toBeGreaterThanOrEqual(20);
  });
});
